+    private ChunkedToXContent deltaChunk(String delta) {
+        return params -> Iterators.concat(
+            ChunkedToXContentHelper.startObject(),
+            ChunkedToXContentHelper.field(RESULT, delta),
+            ChunkedToXContentHelper.endObject()
