+        IbmWatsonxModel ibmWatsonxModel = (IbmWatsonxModel) model;
+
+        var action = ibmWatsonxModel.accept(getActionCreator(getSender(), getServiceComponents()), taskSettings, inputType);
+        action.execute(input, timeout, listener);
