+
+        streamingResponseHandler.onComplete();
+
+        verify(downstreamSubscriber, times(1)).onSubscribe(any());
+        verify(downstreamSubscriber, times(1)).onComplete();
+    }
+
+    public void testErrorForwardsError() {
